const C_GREEN = 0x76c043, C_TRAJ = 0x8dce4a, C_FLASH = 0xcfff9e;
const FOIL = new THREE.Vector3(3.6, 0, 0);
const RING_R = 2.5, RING_T = 0.12, RING_H = 1.25;

/* ── lights (only the foil uses a lit material) ──────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.62));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.9);
keyLight.position.set(-6, 8, 6);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.3);
fillLight.position.set(6, 2, -5);
scene.add(fillLight);

const blackMat = new THREE.LineBasicMaterial({ color: 0x111111 });

/* ── helpers ─────────────────────────────────────────────────────────── */
const V = (x, y, z) => new THREE.Vector3(x, y, z);

function gradientBoxGeo(w, h, dd, faces) {
  const geo = new THREE.BoxGeometry(w, h, dd);
  const pos = geo.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const order = ['px', 'nx', 'py', 'ny', 'pz', 'nz'];
  const c0 = new THREE.Color(), c1 = new THREE.Color(), cc = new THREE.Color();
  for (let f = 0; f < 6; f++) {
    const spec = faces[order[f]];
    c0.set(spec[0]); c1.set(spec[1]);
    for (let i = f * 4; i < f * 4 + 4; i++) {
      let t;
      if (order[f] === 'py' || order[f] === 'ny') t = (pos.getZ(i) + dd / 2) / dd;
      else t = (pos.getY(i) + h / 2) / h;
      cc.copy(c0).lerp(c1, t);
      colors[i * 3] = cc.r; colors[i * 3 + 1] = cc.g; colors[i * 3 + 2] = cc.b;
    }
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  return geo;
}

function shadeCylinder(geo, bottomCol, topCol, h) {
  const pos = geo.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const cb = new THREE.Color(bottomCol), ct = new THREE.Color(topCol), cc = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const t = (pos.getY(i) + h / 2) / h;
    cc.copy(cb).lerp(ct, t);
    const ang = Math.atan2(pos.getZ(i), pos.getX(i));
    const lit = 0.9 + 0.14 * Math.cos(ang - Math.PI * 0.72);
    colors[i * 3] = Math.min(1, cc.r * lit);
    colors[i * 3 + 1] = Math.min(1, cc.g * lit);
    colors[i * 3 + 2] = Math.min(1, cc.b * lit);
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  return geo;
}

function tubeBetween(a, b, r, color, order) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-4);
  const mesh = new THREE.Mesh(
    new THREE.CylinderGeometry(r, r, len, 8, 1),
    new THREE.MeshBasicMaterial({ color, depthTest: false })
  );
  mesh.quaternion.setFromUnitVectors(V(0, 1, 0), dir.clone().normalize());
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.renderOrder = order || 6;
  return mesh;
}

/* ── 1. source housing (shaded grey gradient) ────────────────────────── */
const boxGeo = gradientBoxGeo(3.4, 2.0, 2.2, {
  px: ['#515D59', '#9BA6A1'],
  nx: ['#4A544F', '#8E9994'],
  py: ['#C2CBC6', '#EDF2EF'],
  ny: ['#3B4442', '#4C5754'],
  pz: ['#4C5754', '#B2BCB8'],
  nz: ['#586461', '#9AA49F']
});
const boxMesh = new THREE.Mesh(boxGeo, new THREE.MeshBasicMaterial({ vertexColors: true }));
boxMesh.position.set(-7, 0, 0);
scene.add(boxMesh);
const boxOutline = new THREE.LineSegments(new THREE.EdgesGeometry(boxGeo), blackMat);
boxOutline.position.copy(boxMesh.position);
scene.add(boxOutline);
registerInteractive(boxMesh, {
  title: 'Lead source housing',
  tooltip: 'Radium sealed in lead',
  body: 'A radium sample is sealed inside a block of lead. Lead absorbs α particles in every direction except along a narrow drilled bore, so what leaves the block is a single collimated beam.'
});

/* dashed internal bore */
const boreEdges = new THREE.EdgesGeometry(new THREE.BoxGeometry(2.4, 0.8, 0.8));
const bore = new THREE.LineSegments(boreEdges, new THREE.LineDashedMaterial({
  color: 0x1c221f, dashSize: 0.13, gapSize: 0.1, depthTest: false
}));
bore.computeLineDistances();
bore.position.set(-7, 0, 0);
bore.renderOrder = 4;
scene.add(bore);

/* aperture on the +X face */
const aperture = new THREE.Mesh(
  new THREE.PlaneGeometry(0.35, 0.7),
  new THREE.MeshBasicMaterial({ color: 0x39413e, side: THREE.DoubleSide })
);
aperture.rotation.y = Math.PI / 2;
aperture.position.set(-5.296, 0, 0);
scene.add(aperture);
const apEdge = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.PlaneGeometry(0.35, 0.7)),
  new THREE.LineBasicMaterial({ color: 0x202624 })
);
apEdge.rotation.copy(aperture.rotation);
apEdge.position.copy(aperture.position);
scene.add(apEdge);

/* radium dot + white halo */
const srcDot = new THREE.Mesh(
  new THREE.SphereGeometry(0.16, 20, 16),
  new THREE.MeshBasicMaterial({ color: 0x5fb32e, depthTest: false })
);
srcDot.position.set(-8, 0, 0);
srcDot.renderOrder = 8;
scene.add(srcDot);
const halo = new THREE.Mesh(
  new THREE.TorusGeometry(0.235, 0.06, 10, 32),
  new THREE.MeshBasicMaterial({ color: 0xffffff, depthTest: false })
);
halo.position.copy(srcDot.position);
halo.renderOrder = 7;
scene.add(halo);
registerInteractive(srcDot, {
  title: 'Radium source of α particles',
  tooltip: 'Radium: α emitter',
  body: 'Radium decays by α emission — each α particle is a helium nucleus, charge +2e and mass ≈4 u, moving at roughly 1.5×10⁷ m/s.'
});

/* ── 2. beam (drawn over the housing and the near ring wall) ─────────── */
const beam = tubeBetween(V(-8, 0, 0), V(3.6, 0, 0), 0.09, C_GREEN, 5);
scene.add(beam);
registerInteractive(beam, {
  title: 'Beam of α particles',
  tooltip: 'Collimated α beam',
  body: 'The bore in the lead block collimates the emission into a narrow, straight beam aimed at the centre of the gold foil.'
});

/* ── 3. luminescent screen ring ──────────────────────────────────────── */
const ring = new THREE.Group();
ring.position.copy(FOIL);

const innerGeo = shadeCylinder(
  new THREE.CylinderGeometry(RING_R, RING_R, RING_H, 96, 1, true), '#d3e7cf', '#f2f8f0', RING_H);
const innerWall = new THREE.Mesh(innerGeo,
  new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.BackSide }));

const outerGeo = shadeCylinder(
  new THREE.CylinderGeometry(RING_R + RING_T, RING_R + RING_T, RING_H, 96, 1, true), '#8d9491', '#cdd4d0', RING_H);
const outerWall = new THREE.Mesh(outerGeo,
  new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.FrontSide }));

ring.add(innerWall, outerWall);

const rimTop = new THREE.Mesh(
  new THREE.RingGeometry(RING_R, RING_R + RING_T, 96),
  new THREE.MeshBasicMaterial({ color: 0x8c918e, side: THREE.DoubleSide })
);
rimTop.rotation.x = -Math.PI / 2;
rimTop.position.y = RING_H / 2;
const rimBot = new THREE.Mesh(
  new THREE.RingGeometry(RING_R, RING_R + RING_T, 96),
  new THREE.MeshBasicMaterial({ color: 0x77807c, side: THREE.DoubleSide })
);
rimBot.rotation.x = -Math.PI / 2;
rimBot.position.y = -RING_H / 2;
ring.add(rimTop, rimBot);

/* crisp silhouette rims, like the source's drawn outline */
const rimLineMat = new THREE.LineBasicMaterial({ color: 0x6f7874 });
for (const y of [RING_H / 2, -RING_H / 2]) {
  for (const rad of [RING_R, RING_R + RING_T]) {
    const pts = [];
    for (let i = 0; i <= 96; i++) {
      const a = (i / 96) * Math.PI * 2;
      pts.push(V(Math.cos(a) * rad, y, Math.sin(a) * rad));
    }
    const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), rimLineMat);
    ring.add(l);
  }
}
scene.add(ring);
registerInteractive(innerWall, {
  title: 'Luminescent screen',
  tooltip: 'Zinc-sulfide screen (full circle)',
  body: 'A zinc-sulfide screen encircles the foil. Every α particle that strikes it produces a tiny flash (scintillation) that Geiger and Marsden counted by eye in a darkened room. Because the screen is a complete circle, deflections at ANY angle — even backwards — get recorded.'
});
registerInteractive(outerWall, {
  title: 'Luminescent screen',
  tooltip: 'Zinc-sulfide screen (full circle)',
  body: 'The pale inner face of this hoop is coated with zinc sulfide. Its full-circle geometry is the key design choice: a detector placed only behind the foil would never have revealed the backward-scattered particles.'
});

/* ── 4. gold foil ────────────────────────────────────────────────────── */
const foilGeo = new THREE.BoxGeometry(0.12, 1.0, 0.55);
const foil = new THREE.Mesh(foilGeo, new THREE.MeshLambertMaterial({
  color: 0xf5c13a, emissive: 0x6d5210, depthTest: false
}));
foil.position.copy(FOIL);
foil.rotation.y = THREE.MathUtils.degToRad(10);
foil.renderOrder = 9;
scene.add(foil);
const foilEdge = new THREE.LineSegments(
  new THREE.EdgesGeometry(foilGeo),
  new THREE.LineBasicMaterial({ color: 0xd89b1e, depthTest: false })
);
foilEdge.position.copy(foil.position);
foilEdge.rotation.copy(foil.rotation);
foilEdge.renderOrder = 10;
scene.add(foilEdge);
registerInteractive(foil, {
  title: 'Thin gold foil',
  tooltip: 'Gold foil, a few atoms thick',
  body: 'Gold is hammered into a foil only a few hundred atoms thick. Almost all of its volume turns out to be empty space — the α particles sail through it — yet a tiny fraction hit something dense and charged: the nucleus.'
});

/* ── 5. trajectories + scintillations ────────────────────────────────── */
const trajGroup = new THREE.Group();
scene.add(trajGroup);
let trajectories = { straight: [], slight: [], large: [], all: [] };

function rngFrom(s) { let x = s; return () => { x = (x * 1664525 + 1013904223) % 4294967296; return x / 4294967296; }; }

function endPoint(azDeg, elDeg) {
  const a = THREE.MathUtils.degToRad(azDeg), e = THREE.MathUtils.degToRad(elDeg);
  return V(
    FOIL.x + Math.cos(a) * Math.cos(e) * RING_R,
    FOIL.y + Math.sin(e) * RING_R,
    FOIL.z + Math.sin(a) * Math.cos(e) * RING_R
  );
}

function addTrajectory(azDeg, elDeg, bucket, radius) {
  const end = endPoint(azDeg, elDeg);
  const tube = tubeBetween(FOIL, end, radius, C_TRAJ, 6);
  trajGroup.add(tube);
  const discMat = new THREE.MeshBasicMaterial({
    color: C_FLASH, transparent: true, opacity: 0.85,
    side: THREE.DoubleSide, depthTest: false
  });
  const disc = new THREE.Mesh(new THREE.CircleGeometry(0.085, 18), discMat);
  disc.position.copy(end);
  disc.lookAt(FOIL);
  disc.renderOrder = 7;
  trajGroup.add(disc);
  const t = { end, disc, discMat, flash: 0 };
  trajectories[bucket].push(t);
  trajectories.all.push(t);
  return t;
}

function buildTrajectories(layers) {
  for (const o of trajGroup.children.slice()) {
    trajGroup.remove(o);
    o.geometry?.dispose?.();
    o.material?.dispose?.();
  }
  trajectories = { straight: [], slight: [], large: [], all: [] };

  // straight through: within ±3° of +X (thicker — this is the main bundle)
  [[0, 0], [2.6, 1.4], [-2.4, -1.3], [1.1, -2.2], [-1.3, 2.2]]
    .forEach(([a, e]) => addTrajectory(a, e, 'straight', 0.042));

  // slight deflections: 8°–25° off axis, count grows with foil thickness
  const nSlight = Math.min(16, Math.round(2 + 0.8 * layers));
  const r = rngFrom(20250923);
  for (let i = 0; i < nSlight; i++) {
    const sign = i % 2 ? 1 : -1;
    const mag = 8 + (i / Math.max(1, nSlight - 1)) * 17 + r() * 3;
    const inPlane = r() < 0.55;
    const az = sign * mag * (inPlane ? 1 : 0.55);
    const el = inPlane ? (r() - 0.5) * 6 : sign * (6 + r() * 8);
    addTrajectory(az, el, 'slight', 0.034);
  }

  // large-angle deflections: fixed count, independent of thickness
  [[70, 5], [118, -4], [-142, 3], [-96, 8]]
    .forEach(([a, e]) => addTrajectory(a, e, 'large', 0.036));

  document.getElementById('slightCount').textContent = nSlight;
  document.getElementById('largeCount').textContent = trajectories.large.length;
}
buildTrajectories(4);

/* ── 6. particle pool ────────────────────────────────────────────────── */
const pMat = new THREE.MeshBasicMaterial({ color: 0x4f9c26, depthTest: false });
const pGeo = new THREE.SphereGeometry(0.075, 10, 8);
const particles = [];
for (let i = 0; i < 46; i++) {
  const m = new THREE.Mesh(pGeo, pMat);
  m.visible = false;
  m.renderOrder = 11;
  scene.add(m);
  particles.push({ mesh: m, active: false, phase: 0, s: 0, traj: null });
}
const START = V(-8, 0, 0);
const LEG1 = FOIL.clone().sub(START).length();
const SPEED = 9.5;

function spawnParticle() {
  const p = particles.find(q => !q.active);
  if (!p) return;
  const r = Math.random();
  const bucket = r < 0.87 ? 'straight' : (r < 0.985 ? 'slight' : 'large');
  const list = trajectories[bucket].length ? trajectories[bucket] : trajectories.straight;
  p.traj = list[Math.floor(Math.random() * list.length)];
  p.active = true; p.phase = 0; p.s = 0;
  p.mesh.visible = true;
  p.mesh.position.copy(START);
}

/* ── 7. leader lines + labels ────────────────────────────────────────── */
const leaderGroup = new THREE.Group();
scene.add(leaderGroup);
const leaderMat = new THREE.LineBasicMaterial({ color: 0x000000, depthTest: false });
function leader(a, b) {
  const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints([a, b]), leaderMat);
  l.renderOrder = 12;
  leaderGroup.add(l);
}

leader(V(-8, -0.2, 0), V(-7.5, -2.55, 0));                 // radium source
leader(V(-2.4, 0.13, 0), V(-2.4, 2.25, 0));                // beam
leader(V(2.9, -0.5, 2.15), V(2.0, -2.5, 1.1));             // luminescent screen
leader(V(3.72, -0.5, 0.25), V(4.95, -2.15, 0));            // gold foil
leader(V(5.75, 0.06, 0), V(6.5, 2.6, 0));                  // most pass straight
leader(V(4.85, 0.55, 0.85), V(3.95, 2.8, 0));              // a few slightly deflected
leader(V(1.85, 0.2, 0.95), V(-0.15, 2.85, 0));             // very small number

const labelEntries = [];
function L(html, pos, offset, size) {
  labelEntries.push(addLabel(html, pos, { offset, fontSize: size || '13px' }));
}
L('Radium source of &alpha; particles', V(-7.5, -2.55, 0), [0, 16]);
L('Beam of<br>&alpha; particles', V(-2.4, 2.25, 0), [0, -22]);
L('Luminescent screen<br>to detect scattered<br>&alpha; particles', V(2.0, -2.5, 1.1), [0, 32]);
L('Thin gold<br>foil', V(4.95, -2.15, 0), [10, 26]);
L('Most &alpha; particles<br>pass straight<br>through foil', V(6.5, 2.6, 0), [-4, -28]);
L('A few &alpha;<br>particles are<br>slightly deflected', V(3.95, 2.8, 0), [-16, -28]);
L('A very small number<br>of &alpha; particles<br>are significantly<br>deflected', V(-0.15, 2.85, 0), [-24, -34]);

/* ── 8. camera (after all geometry) — low, near edge-on like the source ─ */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 3.5, z: 30 },   // beam nearly horizontal, depth drops ~30° → elev ≈ 11°
  rollDeg: 0,
  heightFraction: 0.62
});
controls.maxPolarAngle = Math.PI * 0.5 - 0.02;
document.getElementById('btnReset').style.display = '';

/* ── 9. controls ─────────────────────────────────────────────────────── */
const btnFire = document.getElementById('btnFire');
const thickSlider = document.getElementById('thick');
const thickVal = document.getElementById('thickVal');
const chkLabels = document.getElementById('chkLabels');

let firing = false;
let currentLayers = 4;
let targetLayers = 4;
let displayLayers = 4;

btnFire.addEventListener('click', () => {
  firing = !firing;
  btnFire.classList.toggle('active', firing);
  btnFire.textContent = firing ? '■ Stop the beam' : '▶ Fire the α-particle beam';
  if (!firing) {
    for (const p of particles) { p.active = false; p.mesh.visible = false; }
  }
});

thickSlider.addEventListener('input', () => {
  targetLayers = displayLayers = +thickSlider.value;
  applyLayers(+thickSlider.value);
});

function applyLayers(n) {
  n = Math.max(1, Math.min(20, Math.round(n)));
  if (n === currentLayers) return;
  currentLayers = n;
  buildTrajectories(n);
  for (const p of particles) { p.active = false; p.mesh.visible = false; }
}

function setLabels(on) {
  chkLabels.checked = on;
  for (const e of labelEntries) e.div.style.opacity = on ? '1' : '0';
  leaderGroup.visible = on;
}
chkLabels.addEventListener('change', () => setLabels(chkLabels.checked));

/* ── 10. guided demo ─────────────────────────────────────────────────── */
const steps = [
  { title: '1 · The apparatus', text: 'A radium source sealed in a lead block emits α particles; a narrow bore collimates them into a single green beam aimed at a thin gold foil at the centre of a circular luminescent screen.', labels: true, layers: 4, fire: false },
  { title: '2 · Fire the beam', text: 'Watch the particles stream in. Nearly all punch straight through and flash on the far wall; a few swerve by a small angle; one in many thousands ricochets wildly — some back toward the source.', labels: true, layers: 4, fire: true },
  { title: '3 · Thicken the foil', text: 'More atomic layers ⇒ far more small-angle deflections (each particle grazes more atoms) — yet the rate of violent backscatter barely moves.', labels: true, layers: 18, fire: true },
  { title: '4 · Thin it back down', text: 'With a single atomic layer almost everything goes straight through — but the rare large-angle events persist. Something extremely small, dense and charged sits inside each atom.', labels: true, layers: 1, fire: true },
  { title: '5 · Self-quiz', text: 'Labels off. Identify the source housing, the collimated beam, the gold foil and the luminescent screen from geometry alone.', labels: false, layers: 4, fire: false }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepText').textContent = s.text;
  setLabels(s.labels);
  targetLayers = s.layers;
  if (s.fire !== firing) btnFire.click();
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

/* ── 11. update loop (own rAF; scaffold's animate() renders) ─────────── */
let lastT = performance.now();
let spawnAcc = 0;
(function update() {
  requestAnimationFrame(update);
  const now = performance.now();
  const dt = Math.min(0.05, (now - lastT) / 1000);
  lastT = now;

  if (Math.abs(displayLayers - targetLayers) > 0.02) {
    displayLayers += (targetLayers - displayLayers) * Math.min(1, dt * 4.5);
    thickSlider.value = Math.round(displayLayers);
    applyLayers(displayLayers);
  }
  thickVal.textContent = currentLayers;

  const pulse = 1 + 0.12 * Math.sin(now * 0.006);
  srcDot.scale.setScalar(pulse);

  if (firing) {
    spawnAcc += dt;
    while (spawnAcc > 0.1) { spawnAcc -= 0.1; spawnParticle(); }
  }
  for (const p of particles) {
    if (!p.active) continue;
    p.s += SPEED * dt;
    if (p.phase === 0) {
      if (p.s >= LEG1) { p.phase = 1; p.s -= LEG1; }
      else { p.mesh.position.set(START.x + p.s, 0, 0); continue; }
    }
    const seg = p.traj.end.clone().sub(FOIL);
    const len = seg.length();
    if (p.s >= len) {
      p.active = false;
      p.mesh.visible = false;
      p.traj.flash = 1;
    } else {
      p.mesh.position.copy(FOIL).addScaledVector(seg.normalize(), p.s);
    }
  }

  for (const t of trajectories.all) {
    if (t.flash > 0) {
      t.flash = Math.max(0, t.flash - dt / 0.6);
      t.discMat.opacity = 0.7 + 0.3 * t.flash;
      t.disc.scale.setScalar(1 + 1.1 * t.flash);
    } else if (t.disc.scale.x !== 1) {
      t.disc.scale.setScalar(1);
      t.discMat.opacity = 0.85;
    }
  }
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
CONTEXT FROM TEXTBOOK:
This figure shows a schematic diagram of the Geiger-Rutherford gold foil experiment, depicting the complete apparatus from alpha-particle source to detection. On the left, a labeled radium source of alpha particles emits a collimated green beam that travels horizontally to the right toward a thin gold foil mounted at the center of a circular luminescent screen, with the screen encircling the foil to capture scattered particles at any angle. Four labeled outcomes illustrate the three types of trajectories observed: most alpha particles pass straight through the foil undeflected, a few are slightly deflected at small angles, and a very small number are significantly deflected at large angles, including backward toward the source. The circular luminescent screen enables detection across the full angular range, making even the rare large-angle backscattering events observable. This figure introduces the experimental setup whose unexpected results — particularly the small fraction of particles deflected at large angles — provided the empirical evidence that Rutherford used to reject the Thomson plum-pudding model and propose instead a nuclear model of the atom with charge and mass concentrated in a tiny central nucleus.

PROJECTION TYPE: axonometric
Use ordinary orthographic projection: setCameraView({ projection: 'orthographic', axisScreenAngles, heightFraction }). If the plan gives axis_screen_angles: null (a flat 2D plot/diagram), pass axisScreenAngles: null for a front-on view. Otherwise the plan does not measure per-figure angles — use a standard isometric pose: axisScreenAngles: { x: 30, z: 30 }. The source image is a PROJECTION of a 3D object: rebuild the true object — a rectangle stays a rectangle in world space — and let the camera do the projecting. Never bake the drawn parallelogram into the geometry, and never shear geometry. Omit zoom and call setCameraView after all geometry is added — the scaffold auto-fits from the projected bounding box.

ELEMENTS TO RECREATE IN 3D:
  - Rectangular lead source housing (box) at far left, drawn with a shaded gray gradient and a visible top face and right-hand end face
  - Dashed rectangular outline inside the housing marking the hollow bore/cavity that collimates the beam
  - Small bright green radium source dot with white halo at the left end of the internal cavity
  - Small dark rectangular aperture (collimator slit) on the right-hand face of the housing where the beam exits
  - Straight horizontal green alpha-particle beam running from the source dot, out of the aperture, across open space to the gold foil
  - Thin upright gold foil plate (yellow/orange) standing at the exact center of the circular screen
  - Circular luminescent screen: a vertical-axis cylindrical band (ring/hoop) with gray outer surface and pale green inner surface, encircling the foil, open at the top
  - Bundle of undeflected trajectory lines continuing straight through the foil to the far side of the ring
  - Small-angle deflected trajectory lines fanning a few degrees off-axis forward of the foil
  - Large-angle deflected trajectory lines, including several going backward/sideways toward the source side of the ring
  - Bright scintillation flash spots where each trajectory terminates on the inner surface of the screen
  - Leader lines with text labels: 'Radium source of α particles', 'Beam of α particles', 'Luminescent screen to detect scattered α particles', 'Thin gold foil', 'Most α particles pass straight through foil', 'A few α particles are slightly deflected', 'A very small number of α particles are significantly deflected'

GEOMETRY NOTES (world-space scale, color palette, and any formula/value needed for correctness — build to these so sizes, zoom, and colors match the source; do not guess dimensions the notes already specify):
